def run_node(inputs: dict) -> dict:
    calibrated = inputs['node_00']
    b = calibrated['panel_b']
    design = np.column_stack((np.ones(len(b['u'])), b['u']))
    operator = np.linalg.lstsq(design, b['v'], rcond=None)[0]
    return {
        'z_tr': calibrated['u_tr'] @ operator[1:] + operator[0],
        'z_te': calibrated['u_te'] @ operator[1:] + operator[0],
